import { useState } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  address: string;
  city: string;
};

type RegistrationFormProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    name: '',
    email: '',
    address: '',
    city: '',
  });

  const emailError =
    data.email.length > 0 && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const isLastStep = step === STEPS.length - 1;
  const canGoNext = step === 0 ? data.name.trim().length > 0 && !emailError && data.email.length > 0 : true;

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, STEPS.length - 1));

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(data);
    } else {
      goNext();
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-lg, 24px)',
        maxWidth: 480,
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-md, 16px)' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={(event) => setData((prev) => ({ ...prev, name: event.target.value }))}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => setData((prev) => ({ ...prev, email: event.target.value }))}
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-md, 16px)' }}>
          <JxInputField
            label="Адрес"
            required
            value={data.address}
            onChange={(event) => setData((prev) => ({ ...prev, address: event.target.value }))}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => setData((prev) => ({ ...prev, city: event.target.value }))}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-sm, 8px)' }}>
          <p>
            <strong>Имя:</strong> {data.name || '—'}
          </p>
          <p>
            <strong>Email:</strong> {data.email || '—'}
          </p>
          <p>
            <strong>Адрес:</strong> {data.address || '—'}
          </p>
          <p>
            <strong>Город:</strong> {data.city || '—'}
          </p>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-sm, 8px)' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={!canGoNext}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

